    {s:"English",q:"Choose the sentence with correct subject–verb agreement.",o:["The learners walks to school.","The learner walk to school.","The learners walk to school.","The learners is walking to school."],a:2,e:"The plural subject 'learners' takes the plural verb 'walk'."},
    {s:"English",q:"Which word is an adverb in: 'The athlete ran quickly'?",o:["athlete","ran","quickly","the"],a:2,e:"'Quickly' describes how the athlete ran; it is an adverb of manner."},
    {s:"English",q:"Choose the correct reported speech: Mary said, 'I am ready.'",o:["Mary said that I am ready.","Mary said that she was ready.","Mary says she ready.","Mary said she is ready yesterday."],a:1,e:"In ordinary backshifted reported speech, 'I' changes to 'she' and 'am' changes to 'was'."},
    {s:"Kiswahili",q:"Katika sentensi 'Mtoto mchangamfu anaimba', neno 'mchangamfu' ni aina gani ya neno?",o:["Kitenzi","Kivumishi","Kielezi","Kiunganishi"],a:1,e:"'Mchangamfu' linaeleza sifa ya nomino 'mtoto'; kwa hiyo ni kivumishi."},
    {s:"Kiswahili",q:"Wingi wa 'jicho' ni upi?",o:["Majicho","Macho","Vijicho","Machozi"],a:1,e:"Nomino 'jicho' huwa 'macho' katika wingi."},
    {s:"Kiswahili",q:"Katika 'Asha amesoma kitabu', kitenzi ni kipi?",o:["Asha","amesoma","kitabu","Asha amesoma"],a:1,e:"'Amesoma' ndicho kitenzi kinachoonyesha tendo."},
    {s:"Social Studies",q:"Which document is the supreme law of Kenya?",o:["The school constitution","The Constitution of Kenya","A county by-law","The national anthem"],a:1,e:"The Constitution of Kenya is the supreme law and binds all persons and State organs."},
    {s:"Social Studies",q:"Which action demonstrates responsible citizenship?",o:["Destroying public property","Ignoring community needs","Respecting others and obeying lawful rules","Spreading unverified rumours"],a:2,e:"Responsible citizenship includes respect for rights, lawful conduct, participation and care for shared resources."},
    {s:"Agriculture & Nutrition",q:"Which soil particle is generally the largest?",o:["Clay","Silt","Sand","Humus"],a:2,e:"Sand particles are larger than silt and clay particles. Soil also contains organic matter, water and air."},
    {s:"Agriculture & Nutrition",q:"Why is crop rotation useful?",o:["It always removes the need for water","It can interrupt pest cycles and help maintain soil fertility","It makes all soils identical","It prevents every plant disease"],a:1,e:"Rotating crops can reduce the build-up of crop-specific pests and diseases; including legumes can add nitrogen to soil."},
    {s:"Pre-Technical Studies",q:"What should be done before using a hand tool?",o:["Check it for damage and use the correct tool for the task","Borrow a damaged tool","Remove its handle","Use it without instructions"],a:0,e:"Inspect tools, select the correct tool, use appropriate protective equipment and follow the teacher's safety instructions."},
    {s:"Pre-Technical Studies",q:"Which drawing instrument is used to draw a circle?",o:["Set square","Compass","T-square","Protractor only"],a:1,e:"A compass holds a pencil or lead at a fixed radius and is used to draw circles and arcs."},
    {s:"CRE",q:"Which value is shown by helping a neighbour without expecting payment?",o:["Selfishness","Compassion","Dishonesty","Pride"],a:1,e:"Compassion means noticing another person's difficulty and responding with care and helpfulness."},
    {s:"Creative Arts & Sports",q:"Which are the three primary colours in traditional pigment mixing?",o:["Green, orange and purple","Red, yellow and blue","Black, white and grey","Pink, brown and green"],a:1,e:"In traditional paint/pigment colour theory, red, yellow and blue are commonly taught as primary colours."}
