  quiz.push(
    {s:"Mathematics",q:"Convert 0.45 to a percentage.",o:["4.5%","45%","0.45%","450%"],a:1,e:"Multiply by 100: 0.45 × 100 = 45%."},
    {s:"Mathematics",q:"Evaluate −7 + 12.",o:["−19","−5","5","19"],a:2,e:"Starting at −7 and moving 12 units right gives 5."},
    {s:"Mathematics",q:"Find the median of 3, 9, 4, 7, 5.",o:["3","4","5","7"],a:2,e:"Arrange the values: 3, 4, 5, 7, 9. The middle value is 5."},
    {s:"Mathematics",q:"A trader buys an item for KSh 500 and sells it for KSh 650. Find the profit.",o:["KSh 100","KSh 150","KSh 200","KSh 1,150"],a:1,e:"Profit = selling price − cost price = 650 − 500 = KSh 150."},
    {s:"Integrated Science",q:"Which state of matter has a fixed volume but no fixed shape?",o:["Solid","Liquid","Gas","Plasma only"],a:1,e:"A liquid has a fixed volume but takes the shape of its container."},
    {s:"Integrated Science",q:"Which organ pumps blood around the human body?",o:["Lungs","Kidney","Heart","Stomach"],a:2,e:"The heart is a muscular organ that pumps blood through the circulatory system."},
    {s:"Integrated Science",q:"Which force opposes motion between surfaces in contact?",o:["Magnetism","Friction","Gravity only","Upthrust"],a:1,e:"Friction acts between surfaces in contact and opposes relative motion or attempted motion."},
    {s:"Integrated Science",q:"Which instrument measures temperature?",o:["Barometer","Thermometer","Rain gauge","Anemometer"],a:1,e:"A thermometer is used to measure temperature."},
    {s:"English",q:"Choose the correctly punctuated direct speech.",o:["“Where are you going?” asked Ali.","Where are you going? asked Ali.","“Where are you going” asked Ali.","Where are you going, asked Ali."],a:0,e:"The spoken question is enclosed in quotation marks and ends with a question mark."},
    {s:"English",q:"Which sentence is in the past tense?",o:["She walks home.","She is walking home.","She walked home.","She will walk home."],a:2,e:"'Walked' is the simple past tense form."},
    {s:"English",q:"What is the main purpose of a topic sentence?",o:["To introduce the paragraph's main idea","To list every reference","To end the whole essay","To replace punctuation"],a:0,e:"A topic sentence tells the reader the central idea developed in the paragraph."},
    {s:"English",q:"Which is the most suitable formal salutation to a headteacher?",o:["Hey there!","Dear Headteacher,","Hi buddy,","What's up?"],a:1,e:"A formal letter uses a respectful salutation such as 'Dear Headteacher'."},
    {s:"Kiswahili",q:"Wakati ujao wa 'Ninasoma' ni upi?",o:["Nilisoma","Nitasoma","Nimesoma","Nasoma"],a:1,e:"'Nitasoma' huonyesha tendo litakalofanyika baadaye."},
    {s:"Kiswahili",q:"Sehemu ya mwisho ya insha huitwaje?",o:["Utangulizi","Kiini","Hitimisho","Kichwa"],a:2,e:"Hitimisho hufunga insha na kusisitiza ujumbe mkuu."},
    {s:"Kiswahili",q:"Methali 'Umoja ni nguvu' inasisitiza nini?",o:["Ushirikiano","Ubinafsi","Haraka","Uvivu"],a:0,e:"Methali hii inaonyesha kuwa watu wakishirikiana wanaweza kutimiza mambo kwa ufanisi."},
    {s:"Kiswahili",q:"Neno 'walicheza' linaonyesha wakati gani?",o:["Uliopo","Ujao","Uliopita","Amri"],a:2,e:"Kiambishi 'li' katika 'walicheza' kinaonyesha wakati uliopita."},
    {s:"Social Studies",q:"Which level of government is responsible for many devolved county services?",o:["County government","School council","Foreign government","Private companies only"],a:0,e:"County governments perform functions assigned to them by the Constitution, including many devolved services."},
    {s:"Social Studies",q:"What is the long-term pattern of weather in a place called?",o:["Climate","Forecast","Seasonal event","Daily weather"],a:0,e:"Climate describes long-term patterns of atmospheric conditions in a region."},
    {s:"Social Studies",q:"Which is a likely challenge of rapid urbanisation?",o:["No demand for housing","Traffic congestion","No need for water","Automatic reduction of waste"],a:1,e:"Rapid urban growth can increase pressure on transport, housing, water and sanitation."},
    {s:"Social Studies",q:"What does a map key explain?",o:["The age of the map reader","The meaning of map symbols","The weather tomorrow","The population only"],a:1,e:"A map key or legend explains the symbols and colours used on the map."},
    {s:"Agriculture & Nutrition",q:"Which material is suitable for adding organic matter to a compost heap?",o:["Plastic bags","Fresh vegetable peelings","Broken glass","Used batteries"],a:1,e:"Suitable plant-based kitchen scraps can be composted. Batteries, glass and plastics should not be added."},
    {s:"Agriculture & Nutrition",q:"Why should livestock have clean drinking water?",o:["To support body functions and health","To replace all feed","To prevent all diseases","To make housing unnecessary"],a:0,e:"Clean water supports digestion, temperature regulation and other vital body functions."},
    {s:"Agriculture & Nutrition",q:"Which preservation method removes moisture from food?",o:["Drying","Soaking","Washing only","Serving immediately"],a:0,e:"Drying reduces moisture available for many microorganisms, slowing spoilage."},
    {s:"Agriculture & Nutrition",q:"Which practice helps conserve soil moisture?",o:["Mulching","Burning all crop residues","Leaving soil bare","Over-cultivating"],a:0,e:"Mulch covers the soil, reducing evaporation and protecting the surface."},
    {s:"Pre-Technical Studies",q:"What is the mechanical advantage of a machine that lifts 300 N using 100 N effort?",o:["2","3","100","400"],a:1,e:"Mechanical advantage = load ÷ effort = 300 ÷ 100 = 3."},
    {s:"Pre-Technical Studies",q:"What is parallax error?",o:["A tool breaking","A reading error caused by viewing a scale at an angle","A type of material","A safety helmet"],a:1,e:"Viewing a scale from an angle can make the reading appear shifted. Read directly at eye level."},
    {s:"Pre-Technical Studies",q:"Which property is especially important for an electrical tool handle?",o:["Electrical insulation","Transparency only","Solubility","Magnetism only"],a:0,e:"An appropriate insulating handle helps reduce the risk of electric shock."},
    {s:"Pre-Technical Studies",q:"What is a datum edge used for?",o:["A reference edge for accurate marking and measurement","Decorating a finished item","Sharpening a saw","Storing nails"],a:0,e:"A datum edge provides a consistent reference for measurements and marking out."},
    {s:"CRE",q:"Which action best demonstrates integrity?",o:["Cheating when unobserved","Telling the truth and accepting responsibility","Blaming others","Hiding mistakes"],a:1,e:"Integrity means acting honestly and responsibly even when no one is watching."},
    {s:"CRE",q:"What is a peaceful first step when resolving a disagreement?",o:["Shouting louder","Listening to each person's view","Threatening others","Spreading rumours"],a:1,e:"Listening respectfully helps people understand the issue before considering solutions."},
    {s:"CRE",q:"Which action demonstrates stewardship?",o:["Wasting water","Protecting trees and using resources wisely","Littering rivers","Destroying habitats"],a:1,e:"Stewardship involves responsible care for resources and the environment."},
    {s:"CRE",q:"What is a good response to negative peer pressure?",o:["Agree immediately","Refuse respectfully and seek help if needed","Hide the risk","Encourage others to join"],a:1,e:"A clear, respectful refusal and support from a trusted adult can help a learner stay safe."},
    {s:"Creative Arts & Sports",q:"What is the steady pulse in music called?",o:["Beat","Texture","Colour","Shape"],a:0,e:"The beat is the steady underlying pulse in music."},
    {s:"Creative Arts & Sports",q:"Which element helps create loud and soft contrasts in music?",o:["Dynamics","Map scale","Soil texture","Perspective"],a:0,e:"Dynamics describe variations in loudness and softness."},
    {s:"Creative Arts & Sports",q:"Which is an important part of a drama scene?",o:["Characters and a situation","Only a scoreboard","A soil profile","A compass"],a:0,e:"Drama uses characters, situation, action, voice and movement to communicate a story or idea."},
    {s:"Creative Arts & Sports",q:"Which behaviour demonstrates fair play?",o:["Ignoring rules","Respecting officials and opponents","Using unsafe tackles","Excluding teammates"],a:1,e:"Fair play includes following rules, respecting officials and opponents and supporting teammates."}
  );

  const lessons = [
    {id:"math",s:"Mathematics",icon:"➗",intro:"Build confidence by showing each step, checking units and explaining why a method works.",topics:[
      {t:"Percentages in everyday life",level:"Core skill",body:"A percentage means 'out of one hundred'. To change a percentage to a decimal, divide by 100. To find p% of a quantity, multiply the quantity by p/100.",steps:["Write the percentage as a fraction over 100.","Multiply by the whole quantity.","For a discount, subtract the discount from the original price; for an increase, add it."],example:"Find 15% of KSh 600: 15/100 × 600 = KSh 90. A 15% discount gives a new price of 600 − 90 = KSh 510.",practice:"A bag costs KSh 1,200 and is discounted by 20%. Find the discount and the new price.",answer:"20/100 × 1,200 = KSh 240 discount. New price = 1,200 − 240 = KSh 960."},
      {t:"Ratio and proportion",level:"Core skill",body:"A ratio compares quantities in the same units. Simplify a ratio by dividing every term by their highest common factor. Equivalent ratios are formed by multiplying or dividing all terms by the same non-zero number.",steps:["Convert compared quantities to the same unit.","Write the ratio in the given order.","Divide all terms by their highest common factor.","Use equivalent ratios to share or scale quantities."],example:"Share 36 mangoes in the ratio 2:4. Total parts = 6; one part = 36 ÷ 6 = 6. Shares are 12 and 24 mangoes.",practice:"Share KSh 840 in the ratio 3:4.",answer:"Total parts = 7. One part = 840 ÷ 7 = 120. Shares: KSh 360 and KSh 480."},
      {t:"Area of triangles and parallelograms",level:"Measurement",body:"Area measures the surface covered by a flat shape and is expressed in square units. Triangle area is half the product of its base and perpendicular height. Parallelogram area is base multiplied by perpendicular height.",steps:["Identify the base.","Identify the perpendicular height, not the sloping side.","Substitute values with the correct units.","Write the answer in square units."],example:"Triangle: base 10 cm, perpendicular height 6 cm. Area = ½ × 10 × 6 = 30 cm².",practice:"A parallelogram has base 9 m and perpendicular height 4 m. Find its area.",answer:"Area = 9 × 4 = 36 m²."}
    ]},
    {id:"science",s:"Integrated Science",icon:"🔬",intro:"Observe carefully, ask testable questions, record evidence and explain conclusions using scientific ideas.",topics:[
      {t:"The water cycle",level:"Earth and environment",body:"Water moves continuously between Earth's surface and atmosphere. The Sun provides energy for evaporation and transpiration. Water vapour cools and condenses into droplets; precipitation returns water to land and water bodies. Infiltration and runoff move water through the environment.",steps:["Evaporation: liquid water changes to vapour.","Transpiration: plants release water vapour.","Condensation: vapour cools into tiny droplets.","Precipitation: water falls as rain, hail or snow.","Collection, infiltration and runoff return water to stores."],example:"After rain, puddles become smaller on a warm day because liquid water evaporates. Clouds form when moist air cools and water vapour condenses.",practice:"Explain two ways trees contribute to the water cycle.",answer:"Trees absorb water through roots and release water vapour through transpiration. Their roots also help water infiltrate soil and reduce rapid runoff."},
      {t:"Food chains and ecosystems",level:"Living things",body:"An ecosystem includes living organisms and non-living conditions interacting in an area. Producers make food, consumers obtain energy by eating organisms, and decomposers break down dead material and recycle nutrients. Arrows in a food chain point in the direction energy moves—from food to feeder.",steps:["Identify the producer.","Name the primary consumer that eats the producer.","Add higher-level consumers where appropriate.","Include decomposers in the ecosystem explanation."],example:"Grass → grasshopper → frog → snake. The arrow from grass to grasshopper shows energy transfer from grass to grasshopper.",practice:"Construct a food chain using maize, a rat and an owl. Identify the producer.",answer:"Maize → rat → owl. Maize is the producer because it makes its own food by photosynthesis."},
      {t:"Simple electric circuits",level:"Energy",body:"A simple circuit needs a source of electrical energy, conducting paths and a component that transfers energy. A complete closed path allows current to flow. An open switch breaks the path. Conductors allow charge to move easily; insulators resist charge movement.",steps:["Use a cell or battery as the source.","Connect components with suitable insulated wires.","Close the switch to complete the circuit.","Open the switch before changing connections.","Never experiment with mains electricity."],example:"A cell, wires, switch and bulb connected in one closed loop form a simple circuit. If the wire is disconnected, the bulb goes off.",practice:"Why does a bulb go off when a switch is opened?",answer:"Opening the switch breaks the conducting path, so current no longer flows through the bulb."}
    ]},
    {id:"english",s:"English",icon:"📖",intro:"Read for meaning, choose precise vocabulary and organise ideas into clear paragraphs.",topics:[
      {t:"Subject–verb agreement",level:"Grammar",body:"A verb must agree with its subject in person and number. A singular subject normally takes a singular present-tense verb; a plural subject takes a plural verb. Do not let a nearby noun distract you from the true subject.",steps:["Find the subject of the clause.","Decide whether the subject is singular or plural.","Choose the verb form that agrees.","Check the sentence aloud."],example:"The basket of oranges is heavy. The subject is 'basket' (singular), not 'oranges'; therefore use 'is'.",practice:"Choose the correct form: 'Each of the players (has/have) a water bottle.'",answer:"Has. 'Each' is singular, so it takes the singular verb 'has'."},
      {t:"Writing a coherent paragraph",level:"Composition",body:"A paragraph develops one main idea. A topic sentence introduces the idea; supporting sentences explain it with reasons, examples or evidence; a concluding sentence rounds it off. Use linking words to show sequence, contrast and cause.",steps:["Plan one clear main point.","Write a topic sentence.","Add two or three relevant supporting details.","Use suitable connectors.","End with a concluding sentence and edit punctuation."],example:"School gardens are valuable learning spaces. Learners practise planting, observe plant growth and understand food production. They can also learn teamwork while caring for the garden. Therefore, a school garden connects classroom learning with practical life.",practice:"Write a paragraph explaining one way learners can conserve water at school.",answer:"A strong paragraph has one topic sentence, specific practical details (for example closing taps, reporting leaks or harvesting rainwater), logical connectors and a concluding sentence."},
      {t:"Reading for inference",level:"Comprehension",body:"A literal question asks for information stated directly. An inferential question asks you to combine clues with what you know. Support an inference with evidence from the text; do not invent details that the passage does not support.",steps:["Read the question before returning to the passage.","Underline relevant words or actions.","Combine the clues with a reasonable explanation.","State the inference and cite the clue."],example:"Passage: 'Nia looked at the dark clouds, packed her books in a plastic bag and hurried home.' Inference: she expected rain. Evidence: dark clouds and protecting her books.",practice:"What evidence would support the inference that a character is nervous?",answer:"Clues such as trembling hands, a shaky voice, avoiding eye contact or repeatedly checking the time—provided they appear in the passage."}
    ]},
    {id:"kiswahili",s:"Kiswahili",icon:"🗣️",intro:"Jenga ufasaha kwa kusoma, kusikiliza, kuzungumza na kuandika Kiswahili sanifu.",topics:[
      {t:"Aina za maneno: nomino, vitenzi na vivumishi",level:"Sarufi",body:"Nomino hutaja watu, vitu, mahali au dhana. Vitenzi huonyesha tendo au hali. Vivumishi hutoa maelezo kuhusu nomino. Vielezi hufafanua zaidi tendo, kivumishi au kielezi kingine.",steps:["Soma sentensi nzima.","Tambua neno linalotaja mtu au kitu (nomino).","Tafuta neno linaloonyesha tendo (kitenzi).","Tafuta neno linaloeleza sifa ya nomino (kivumishi)."],example:"Katika 'Mwanafunzi mwerevu anasoma kwa bidii': mwanafunzi = nomino; mwerevu = kivumishi; anasoma = kitenzi; kwa bidii = kielezi cha namna.",practice:"Bainisha aina za maneno katika sentensi: 'Mtoto mdogo anakimbia haraka.'",answer:"Mtoto — nomino; mdogo — kivumishi; anakimbia — kitenzi; haraka — kielezi."},
      {t:"Ngeli za nomino: M-WA na JI-MA",level:"Sarufi",body:"Ngeli huonyesha makundi ya nomino na upatanisho wake katika sentensi. M-WA hujumuisha majina mengi ya watu, kwa mfano mtoto/watoto na mwalimu/walimu. JI-MA hujumuisha majina kama jicho/macho na jiwe/mawe. Upatanisho hutegemea umoja au wingi.",steps:["Tambua nomino katika umoja.","Tafuta umbo lake la wingi.","Angalia upatanisho wa kivumishi na kitenzi.","Tunga sentensi sahihi katika umoja na wingi."],example:"Mtoto mzuri anacheza. Watoto wazuri wanacheza. Nomino, kivumishi na kitenzi vinapatana.",practice:"Badilisha sentensi 'Jicho langu linauma' iwe katika wingi.",answer:"Macho yangu yanauma."},
      {t:"Ufahamu: kusoma na kujibu",level:"Ufahamu",body:"Soma kifungu kwa makini ili kubaini wazo kuu, hoja zinazounga mkono, maana ya msamiati katika muktadha na dhamira ya mwandishi. Jibu kwa sentensi kamili pale swali linapohitaji maelezo.",steps:["Soma kifungu mara ya kwanza kupata ujumbe mkuu.","Soma tena na uweke alama kwa hoja muhimu.","Tazama swali linataka nani, nini, kwa nini au vipi.","Jibu kutokana na ushahidi wa kifungu."],example:"Kifungu: 'Wananchi walipanda miti kandokando ya mto ili kuzuia mmomonyoko wa udongo.' Wazo kuu: upandaji miti husaidia kuhifadhi mazingira na kingo za mito.",practice:"Eleza tofauti kati ya wazo kuu na maelezo yanayounga mkono.",answer:"Wazo kuu ni ujumbe mkuu wa kifungu; maelezo yanayounga mkono ni mifano, sababu au ushahidi unaoifafanua."}
    ]},
    {id:"social",s:"Social Studies",icon:"🌍",intro:"Understand people, places, resources, rights and responsibilities in Kenya and the wider world.",topics:[
      {t:"Responsible citizenship and the Constitution",level:"Citizenship",body:"Citizenship involves belonging to a country and enjoying rights while fulfilling responsibilities. The Constitution of Kenya is the supreme law. It establishes national values, institutions, rights and responsibilities. Rights should be exercised with respect for the rights of others and the law.",steps:["Know that the Constitution is the supreme law.","Respect the rights and dignity of others.","Participate peacefully in community affairs.","Protect public property and the environment.","Seek reliable information and reject discrimination."],example:"Learners electing class representatives fairly are practising participation, accountability and respect for others.",practice:"Give three ways a learner can demonstrate responsible citizenship at school.",answer:"Respect others, follow fair school rules, protect shared property, participate constructively and report safety concerns to a trusted adult."},
      {t:"Maps, direction and scale",level:"Geography",body:"A map is a representation of an area viewed from above. Common map elements include a title, key, scale, direction indicator and symbols. A scale relates distance on a map to actual ground distance. Always use the units stated by the scale.",steps:["Read the map title and key.","Identify north and the other cardinal directions.","Measure the map distance accurately.","Apply the scale and convert units carefully."],example:"If 1 cm represents 5 km, a measured distance of 4 cm represents 4 × 5 = 20 km on the ground.",practice:"On a map with scale 1 cm represents 2 km, two towns are 7.5 cm apart. Find the actual distance.",answer:"7.5 × 2 = 15 km."},
      {t:"Kenya's natural resources and conservation",level:"Environment",body:"Natural resources include water, soil, forests, wildlife, minerals and energy sources. Sustainable use meets present needs while protecting resources for future generations. Conservation includes restoration, wise use, pollution prevention and fair community participation.",steps:["Identify a resource and how people use it.","Explain a pressure or threat to the resource.","Suggest a practical conservation action.","Describe how the action benefits people and ecosystems."],example:"Planting indigenous trees, protecting water catchments and avoiding dumping waste into rivers help conserve water and biodiversity.",practice:"Explain why protecting a water catchment benefits communities downstream.",answer:"Healthy catchments improve infiltration and water storage, reduce erosion and sediment, and help maintain cleaner, more reliable river flows."}
    ]},
    {id:"agri",s:"Agriculture & Nutrition",icon:"🌱",intro:"Connect crop and animal production, soil care, food choices and sustainable household practices.",topics:[
      {t:"Soil texture, structure and conservation",level:"Crop production",body:"Soil texture describes the relative proportions of sand, silt and clay. Soil structure describes how particles form aggregates. Good soil supports roots, stores water and air, and supplies nutrients. Erosion removes fertile topsoil through water or wind.",steps:["Observe soil safely and compare particle feel.","Identify signs of erosion such as rills or exposed roots.","Use ground cover, contour farming, mulching or terraces where suitable.","Add organic matter and avoid unnecessary soil disturbance."],example:"Mulch reduces the impact of raindrops, slows surface water and reduces evaporation while organic mulch gradually decomposes.",practice:"State two ways to reduce soil erosion on a sloping farm.",answer:"Plant grass or cover crops, use contour strips/terraces where appropriate, maintain mulch and avoid leaving soil bare."},
      {t:"Crop growth and plant needs",level:"Crop production",body:"Most crops need suitable light, water, air, nutrients, temperature and space. Seeds generally require moisture, oxygen and suitable warmth to germinate. Healthy seedlings need appropriate spacing, weed control and protection from pests and diseases.",steps:["Select healthy seed and prepare a suitable seedbed.","Provide moisture without waterlogging.","Thin or transplant seedlings at suitable spacing.","Monitor growth and manage weeds and pests safely."],example:"If seedlings are overcrowded, they compete for light, water, nutrients and space; thinning can reduce competition.",practice:"Why is it harmful to overwater seedlings?",answer:"Excess water can displace air from soil pores, limit root respiration and encourage root rot or seedling diseases."},
      {t:"Balanced meals and food hygiene",level:"Nutrition",body:"A balanced diet provides energy, body-building and protective nutrients in appropriate amounts. A varied diet can include staples, legumes, vegetables, fruits and suitable animal-source foods. Food hygiene prevents contamination through clean hands, utensils, safe water, proper cooking and storage.",steps:["Choose a variety of foods from different groups.","Include vegetables and fruits regularly.","Wash hands and utensils before food preparation.","Separate raw and ready-to-eat foods.","Cook thoroughly and store food safely."],example:"A meal of ugali, beans and sukuma wiki provides energy-giving carbohydrate, protein and fibre, vitamins and minerals.",practice:"Give three safe food-handling practices at home.",answer:"Wash hands, use clean utensils and safe water, separate raw foods from cooked foods, cook thoroughly and cover/store food safely."}
    ]},
    {id:"pretech",s:"Pre-Technical Studies",icon:"🛠️",intro:"Plan, design, make and evaluate solutions while putting safety, accuracy and responsible tool use first.",topics:[
      {t:"Workshop safety and hand tools",level:"Practical skills",body:"A safe workspace is organised, well lit and free from unnecessary hazards. Select tools for their intended purpose, inspect them before use and follow demonstrations. Wear suitable protective equipment and report damaged tools immediately.",steps:["Listen to instructions and identify hazards.","Inspect the tool, handle and working area.","Secure the material before cutting or shaping.","Keep hands away from cutting edges.","Clean, return and store tools correctly."],example:"A hand saw is for cutting suitable material; it should be sharp, undamaged and used with the work securely held. Never distract someone using a tool.",practice:"List four checks to make before beginning a practical task.",answer:"Check instructions, tool condition, material security, working space and appropriate protective equipment."},
      {t:"Design process: from problem to prototype",level:"Design thinking",body:"Design begins with a real need. A good process investigates users, defines the problem, develops several ideas, selects criteria, makes a prototype, tests it and improves the design. A prototype is an early model used to learn and refine a solution.",steps:["Identify who has the problem and what they need.","Write a clear problem statement.","Sketch more than one possible solution.","Choose a design using criteria such as safety, cost and function.","Make, test, record feedback and improve."],example:"A learner designs a desk organiser from reused cardboard. The prototype is tested for stability, capacity, durability and ease of use.",practice:"Why should a designer test a prototype before making the final product?",answer:"Testing reveals weaknesses and checks whether the design meets users' needs; feedback guides improvements before more time and materials are used."},
      {t:"Technical drawing: scale and dimension",level:"Drawing skills",body:"Technical drawings communicate shape, size and construction clearly. Use suitable drawing tools, neat lines, correct dimensions and an appropriate scale. A scale drawing changes the size on paper while keeping proportions consistent.",steps:["Choose a suitable scale and write it down.","Draw light construction lines first.","Use a ruler and appropriate set square or compass.","Add clear dimensions and labels.","Darken final outlines and erase unnecessary construction marks."],example:"At a scale of 1:10, a 50 cm object is drawn as 5 cm because drawing length = actual length ÷ 10.",practice:"A 2 m bench is represented at scale 1:20. What is its drawing length in centimetres?",answer:"2 m = 200 cm. 200 ÷ 20 = 10 cm."}
    ]},
    {id:"cre",s:"CRE",icon:"🤝",intro:"Explore faith, moral choices, relationships, service and values through respectful reflection.",topics:[
      {t:"Values in daily decisions",level:"Life and values",body:"Values are principles that guide choices and relationships. Honesty, respect, responsibility, compassion, justice and integrity help people live peacefully. A moral decision considers who may be affected and chooses a fair, caring and responsible action.",steps:["Describe the situation accurately.","Identify people who may be affected.","Consider possible actions and consequences.","Choose an honest, fair and caring response.","Reflect on what could be improved."],example:"If you find a lost exercise book, returning it to its owner or handing it to a teacher shows honesty and responsibility.",practice:"A friend asks you to hide that they damaged shared property. What values can guide your response?",answer:"Be honest and fair: encourage your friend to take responsibility, help report the damage respectfully and seek a way to repair it."},
      {t:"Service and care for others",level:"Community",body:"Service means using one's time, abilities or resources to support others and improve the community. Meaningful service responds to a real need, respects dignity and avoids causing harm. Small acts can make a positive difference.",steps:["Listen to understand a genuine need.","Ask permission and involve appropriate adults.","Plan a safe, practical activity.","Work respectfully with others.","Reflect on the benefit and lessons learned."],example:"A class can organise a supervised litter-picking activity using gloves and safe waste-handling rules, then discuss ways to prevent litter.",practice:"Suggest one safe service activity learners could carry out in their school community.",answer:"Examples include a supervised reading-buddy activity, helping maintain a school garden or organising a respectful cleanliness campaign."}
    ]},
    {id:"arts",s:"Creative Arts & Sports",icon:"🎨",intro:"Develop expression, practice, movement, teamwork and appreciation of creative work.",topics:[
      {t:"Elements of art and composition",level:"Visual arts",body:"Line, shape, form, colour, texture, space and value are elements used to create visual work. Composition is the arrangement of elements. Balance, contrast, emphasis, rhythm, pattern and unity are principles that help organise a composition.",steps:["Decide the message or subject.","Choose elements that support the idea.","Arrange shapes and lines to guide the viewer's eye.","Use contrast or emphasis deliberately.","Review balance and unity."],example:"A poster about water conservation can use a large water-drop image as the focal point, strong contrast for the headline and repeated small symbols to create unity.",practice:"Name three elements of art and explain how one can be used in a poster.",answer:"Examples: line, shape, colour, texture, space and value. Colour can create contrast and draw attention to the main message."},
      {t:"Fitness, warm-up and safe participation",level:"Physical education",body:"Physical activity supports fitness and wellbeing. A warm-up gradually prepares the body for activity; a cool-down allows activity to reduce gradually. Safe participation includes suitable clothing, hydration, space, equipment checks, fair play and adapting activity to ability.",steps:["Check the playing area and equipment.","Begin with light movement and dynamic mobility.","Increase activity gradually.","Use correct technique and respect rules.","Cool down and report pain or injury to a responsible adult."],example:"Before a running activity, learners can walk, jog lightly and perform controlled dynamic movements under teacher guidance.",practice:"Give two reasons for warming up before vigorous exercise.",answer:"A warm-up gradually increases circulation and muscle temperature and prepares the body and mind for activity, helping performance and reducing injury risk."}
    ]}
  ];

  const additionalTopics = {
    math: [
      {t:"Fractions, decimals and percentages",level:"Number",body:"Fractions, decimals and percentages are three ways of representing parts of a whole. Convert between them by using equivalent fractions and place value. Always check that the value remains the same after conversion.",steps:["To convert a fraction to a decimal, divide the numerator by the denominator.","To convert a decimal to a percentage, multiply by 100 and add the % sign.","To convert a percentage to a fraction, write it over 100 and simplify.","Use estimation to check whether the answer is reasonable."],example:"Convert 3/8 to a percentage. 3 ÷ 8 = 0.375. Then 0.375 × 100 = 37.5%.",practice:"Convert 0.625 to a fraction in its simplest form and to a percentage.",answer:"0.625 = 625/1000 = 5/8. As a percentage: 0.625 × 100 = 62.5%."},
      {t:"Integers and order of operations",level:"Number",body:"Integers are positive whole numbers, negative whole numbers and zero. On a number line, values increase to the right. When evaluating expressions, follow brackets, powers, multiplication/division and addition/subtraction in order.",steps:["Place positive and negative numbers on a number line.","For addition of unlike signs, subtract magnitudes and keep the sign of the larger magnitude.","Remember that subtracting a negative is equivalent to adding.","Apply the order of operations consistently."],example:"Evaluate −4 + 3 × 5. Multiply first: 3 × 5 = 15. Then −4 + 15 = 11.",practice:"Evaluate 18 − (−6) ÷ 3.",answer:"Divide first: (−6) ÷ 3 = −2. Then 18 − (−2) = 20."},
      {t:"Data handling: mean, median, mode and range",level:"Statistics",body:"The mean is the sum divided by the number of values. The median is the middle value after arranging data in order. The mode is the most frequent value. The range is the difference between the highest and lowest values.",steps:["Arrange the data in ascending order for median and range.","Add all values and divide by the number of values to find mean.","Locate the middle value (or average the two middle values).","Count frequencies to identify the mode.","Subtract the smallest value from the largest for range."],example:"For 2, 3, 3, 5, 7: mean = 20/5 = 4; median = 3; mode = 3; range = 7 − 2 = 5.",practice:"Find the mean, median, mode and range of 4, 6, 6, 8, 11.",answer:"Mean = 35/5 = 7; median = 6; mode = 6; range = 11 − 4 = 7."}
    ],
    science: [
      {t:"States of matter and particle model",level:"Matter",body:"Matter commonly exists as solids, liquids and gases. In a solid, particles are close together and vibrate about fixed positions. In a liquid, particles remain close but move past one another. In a gas, particles are far apart and move freely and rapidly.",steps:["Compare shape and volume of each state.","Use particle spacing and movement to explain properties.","Describe melting, freezing, evaporation, condensation and sublimation.","Relate changes of state to energy transfer."],example:"When ice melts, it absorbs energy. Its particles gain freedom to move past one another, forming liquid water.",practice:"Explain why a gas can be compressed more easily than a liquid.",answer:"Gas particles are far apart with large spaces between them, so they can be pushed closer together. Liquid particles are already close."},
      {t:"Human body systems and healthy living",level:"Life processes",body:"Body systems work together to maintain life. The digestive system breaks food into absorbable nutrients; the respiratory system exchanges oxygen and carbon dioxide; the circulatory system transports materials; and the excretory system removes metabolic wastes.",steps:["Name the main organs in a body system.","Describe the function of each organ in simple terms.","Explain how two systems work together.","Relate hygiene, nutrition, exercise and rest to health."],example:"During exercise, muscles need more oxygen and glucose. Breathing rate and heart rate increase to deliver oxygen and nutrients and remove carbon dioxide.",practice:"Explain how the respiratory and circulatory systems work together.",answer:"The lungs transfer oxygen into the blood. The heart pumps oxygenated blood to body cells and returns blood carrying carbon dioxide to the lungs for removal."},
      {t:"Forces, friction and motion",level:"Physical science",body:"A force is a push or pull that can change an object's motion, direction or shape. Friction opposes relative motion between surfaces. It can be useful for walking and braking, but it can also cause wear and unwanted heating.",steps:["Identify forces acting on an object.","Distinguish balanced and unbalanced forces.","Describe how friction affects movement.","Suggest ways to increase or reduce friction for a purpose."],example:"Tyre treads and rough road surfaces increase grip, helping a vehicle brake safely. Lubricants reduce friction between moving machine parts.",practice:"Give one useful and one harmful effect of friction.",answer:"Useful: friction between shoes and ground prevents slipping. Harmful: friction between machine parts causes wear and energy loss as heat."}
    ],
    english: [
      {t:"Punctuation and direct speech",level:"Writing skills",body:"Punctuation helps readers understand meaning. Begin a sentence with a capital letter and end it with a full stop, question mark or exclamation mark as appropriate. Direct speech reproduces exact words and is enclosed in quotation marks.",steps:["Use capital letters for sentence beginnings and proper nouns.","Use commas to separate items and after introductory expressions where needed.","Place quotation marks around spoken words.","Use punctuation inside or around the quotation according to the sentence structure."],example:"Amina asked, “Have you completed the assignment?” The question mark belongs to the spoken question.",practice:"Punctuate: peter said i will visit kisumu on friday.",answer:"Peter said, “I will visit Kisumu on Friday.”"},
      {t:"Tenses and consistent verb forms",level:"Grammar",body:"Tense locates an action in time. Simple present describes habits or facts; simple past describes completed past actions; and simple future describes actions expected later. Keep tense consistent unless the time meaning changes.",steps:["Identify when the action happens.","Choose the tense that matches the time.","Check subject–verb agreement.","Avoid shifting tense without a reason."],example:"Every morning, Wanjiku walks to school. Yesterday, she walked with her friend. Tomorrow, she will walk early.",practice:"Rewrite in the past tense: They play football and score two goals.",answer:"They played football and scored two goals."},
      {t:"Formal and informal letter writing",level:"Functional writing",body:"A formal letter is written for official purposes and uses a respectful, clear tone. An informal letter is written to a friend or relative and may use a warmer conversational tone. Both should have a clear purpose and well-organised paragraphs.",steps:["Write the sender's address and date where required by the format.","Include the recipient's address for a formal letter.","Use an appropriate salutation.","State the purpose in the opening paragraph.","Develop the message clearly and close appropriately."],example:"Formal opening: Dear Headteacher, I am writing to request permission for our class to visit the county library.",practice:"List three features that distinguish a formal letter from an informal letter.",answer:"A formal letter uses a formal tone, an official recipient address and a conventional salutation/closing. An informal letter is more personal and conversational."}
    ],
    kiswahili: [
      {t:"Nyakati za vitenzi",level:"Sarufi",body:"Kitenzi hubadilika kulingana na wakati. Wakati uliopo huonyesha tendo linalofanyika sasa; wakati uliopita huonyesha tendo lililokwisha; wakati ujao huonyesha tendo litakalofanyika baadaye. Viambishi vya nafsi na wakati lazima vipatane.",steps:["Tambua mtenda wa tendo.","Chagua kiambishi cha nafsi kinachofaa.","Chagua kiambishi cha wakati.","Tumia mzizi wa kitenzi na uunde sentensi sahihi."],example:"Ninasoma (sasa), nilisoma (zamani), nitasoma (baadaye).",practice:"Badilisha 'Watoto wanacheza' iwe katika wakati uliopita na ujao.",answer:"Wakati uliopita: Watoto walicheza. Wakati ujao: Watoto watacheza."},
      {t:"Uandishi wa insha: utangulizi, kiini na hitimisho",level:"Uandishi",body:"Insha nzuri huwa na utangulizi unaotambulisha mada, kiini chenye aya zinazokuza hoja, na hitimisho linalofunga ujumbe. Kila aya inapaswa kuwa na wazo kuu na maelezo yanayolifafanua.",steps:["Elewa mada na maneno muhimu.","Panga hoja zako kabla ya kuandika.","Andika utangulizi mfupi unaovutia.","Tumia aya tofauti kwa hoja kuu.","Hitimisha kwa muhtasari unaolingana na mada na usahihishe lugha."],example:"Mada: Umuhimu wa usafi shuleni. Hoja zinaweza kuwa afya bora, mazingira mazuri ya kujifunzia na uwajibikaji wa wanafunzi.",practice:"Taja sehemu tatu kuu za insha na kazi ya kila sehemu.",answer:"Utangulizi hutambulisha mada; kiini huendeleza hoja kwa maelezo na mifano; hitimisho hufunga ujumbe mkuu."},
      {t:"Methali, nahau na misemo",level:"Fasihi",body:"Methali ni kauli fupi yenye funzo au hekima. Nahau ni msemo wenye maana isiyo ya moja kwa moja kutokana na maneno yake. Misemo ni kauli zinazotumiwa kueleza hali au wazo kwa namna maalumu.",steps:["Soma kauli katika muktadha wake.","Tambua maana ya kawaida ya maneno.","Tafuta maana fiche au funzo linalokusudiwa.","Tumia kauli katika sentensi inayoonyesha maana yake."],example:"'Haraka haraka haina baraka' hufundisha kuwa kufanya mambo kwa pupa kunaweza kusababisha makosa.",practice:"Eleza funzo la methali 'Umoja ni nguvu, utengano ni udhaifu.'",answer:"Ushirikiano huleta uwezo wa kutimiza jambo kwa urahisi zaidi kuliko watu kufanya kazi kwa kutengana."}
    ],
    social: [
      {t:"Weather, climate and climate adaptation",level:"Geography",body:"Weather describes atmospheric conditions over a short period, while climate describes long-term patterns. Temperature, rainfall, wind and humidity are elements of weather. Communities adapt to climate risks through suitable crops, water storage, early warnings and resilient infrastructure.",steps:["Distinguish daily weather from long-term climate.","Identify elements measured by weather instruments.","Explain how climate affects livelihoods.","Suggest locally appropriate adaptation measures."],example:"A farmer may use drought-tolerant crops, mulching and rainwater harvesting to reduce the effects of unreliable rainfall.",practice:"Give two differences between weather and climate.",answer:"Weather changes over hours or days and describes short-term conditions. Climate is the long-term pattern of conditions in a region, usually assessed over decades."},
      {t:"Kenya's levels of government and public participation",level:"Civics",body:"Kenya has national and county levels of government established by the Constitution. County governments deliver devolved services while national government performs national functions. Public participation allows people to contribute to decisions that affect them.",steps:["Identify national and county government roles.","Recognise that the Constitution allocates functions.","Find appropriate, peaceful ways to participate.","Use reliable information when discussing public issues."],example:"Residents may submit views during a county budget consultation or attend a public participation forum.",practice:"Name two ways citizens can participate in county decision-making.",answer:"They can attend public forums, submit written views, engage elected representatives and follow official consultation notices."},
      {t:"Population, settlement and urbanisation",level:"Human geography",body:"Population refers to people living in an area. Settlement patterns may be dispersed, nucleated or linear. Urbanisation is the growth in the proportion of people living in towns and cities. It can create opportunities and pressure on housing, transport, water and sanitation.",steps:["Describe a settlement pattern from a map or photograph.","Identify reasons people settle in particular places.","Explain causes of rural–urban migration.","Balance benefits and challenges of urban growth."],example:"People may move to a town for education and employment, but rapid growth can increase demand for affordable housing and transport.",practice:"State two possible benefits and two challenges of urbanisation.",answer:"Benefits include jobs and access to services. Challenges include congestion, housing shortages, waste management pressures and informal settlements."}
    ],
    agri: [
      {t:"Composting and organic soil improvement",level:"Soil management",body:"Composting is the controlled decomposition of suitable organic materials into a soil conditioner. A compost pile needs a balance of dry carbon-rich materials, moist nitrogen-rich materials, air and water. Do not add plastics, chemicals, meat or diseased plant material.",steps:["Choose a safe, well-drained composting site.","Layer dry plant materials with suitable green materials.","Keep the pile moist but not waterlogged.","Turn it periodically to supply oxygen.","Use mature, dark, crumbly compost appropriately."],example:"Dry leaves can be mixed with fresh grass clippings and vegetable peelings. Turning the pile helps air enter and supports decomposition.",practice:"Why should a compost heap not be waterlogged?",answer:"Waterlogging removes air spaces and can cause anaerobic decomposition, unpleasant odours and slower composting."},
      {t:"Livestock care, housing and welfare",level:"Animal production",body:"Healthy livestock need suitable feed, clean water, adequate space, ventilation, protection from extreme weather and prompt attention to illness or injury. Housing should be clean, dry, secure and appropriate for the species and age of animals.",steps:["Provide clean water and balanced feed appropriate to the animal.","Keep housing clean, dry and well ventilated.","Observe animals daily for changes in appetite or behaviour.","Seek advice from a qualified animal-health professional when animals are sick.","Handle animals calmly and humanely."],example:"A poultry house needs adequate ventilation, dry litter, clean drinkers and protection from predators.",practice:"List four features of a suitable poultry house.",answer:"Adequate ventilation, dry clean litter, enough space, protection from predators, suitable lighting and access to clean feed and water."},
      {t:"Food preservation and storage",level:"Nutrition",body:"Food preservation slows spoilage caused by microorganisms, enzymes and environmental conditions. Methods include drying, refrigeration, freezing, fermentation and safe heat processing. The method must suit the food and be carried out hygienically.",steps:["Select fresh, sound food materials.","Wash and prepare food using clean water and utensils.","Choose a suitable preservation method.","Use clean, food-safe containers.","Label and store at appropriate conditions; discard food showing unsafe spoilage."],example:"Drying reduces the moisture available for microbial growth. Food should be dried thoroughly and stored in clean, dry, airtight containers.",practice:"Explain how drying helps preserve food.",answer:"Drying removes moisture needed by many microorganisms to multiply, slowing spoilage when the food is properly dried and stored."}
    ],
    pretech: [
      {t:"Materials: properties and selection",level:"Materials technology",body:"Materials are selected according to their properties and intended use. Relevant properties include strength, hardness, flexibility, durability, conductivity, water resistance, cost and environmental impact. No material is best for every purpose.",steps:["Identify the function and conditions of use.","List the properties needed.","Compare available materials against the criteria.","Consider safety, cost, availability and reuse.","Explain and justify the final choice."],example:"A handle may need strength and a comfortable grip. Wood can be shaped and is a poor conductor of heat, while metal may be strong but can become hot.",practice:"Why might plastic be selected for the handle of an electrical tool?",answer:"Suitable insulating plastics reduce the risk of electric shock and can provide a lightweight, mouldable grip; the specific plastic must be rated for the task."},
      {t:"Measurement, accuracy and workshop marking-out",level:"Practical skills",body:"Accurate measurement helps parts fit and reduces waste. Read scales at eye level to avoid parallax error, choose an instrument with suitable precision and mark clearly from a consistent datum edge.",steps:["Check the measuring instrument for damage and zero error where relevant.","Choose units and a datum/reference edge.","Read the scale at eye level.","Mark thin, clear lines with the correct tool.","Measure again before cutting or drilling."],example:"When measuring 125 mm with a ruler, align the object with the zero mark rather than assuming the ruler's edge is exactly zero.",practice:"What is parallax error and how can it be reduced?",answer:"Parallax error is a reading error caused by viewing a scale from an angle. Look directly perpendicular to the scale at the mark."},
      {t:"Simple machines and mechanical advantage",level:"Technology",body:"Simple machines help make work easier by changing the size or direction of a force. Examples include levers, pulleys, inclined planes, wheels and axles, wedges and screws. Mechanical advantage compares the load to the effort.",steps:["Identify the simple machine used.","Name the effort and load.","Describe how the machine changes force or direction.","For an ideal machine, mechanical advantage = load ÷ effort."],example:"If a lever lifts a 300 N load using a 100 N effort, its mechanical advantage is 300 ÷ 100 = 3.",practice:"A pulley system lifts a 400 N load with an effort of 200 N. Find its mechanical advantage.",answer:"Mechanical advantage = load ÷ effort = 400 ÷ 200 = 2."}
    ],
    cre: [
      {t:"Peace, reconciliation and conflict resolution",level:"Moral education",body:"Conflict can arise when people have different needs, opinions or interests. Peaceful resolution uses listening, respect, truthful communication, fairness and, where necessary, a trusted mediator. Violence, threats and humiliation do not create lasting solutions.",steps:["Allow each person to explain their view safely.","Listen without interrupting or insulting.","Identify the issue rather than attacking a person.","Explore fair solutions and agree on practical steps.","Seek help from a trusted adult if anyone is unsafe."],example:"Two learners disagree over group roles. They can list tasks, share responsibilities fairly and ask the teacher to mediate if the disagreement continues.",practice:"Give three behaviours that can help resolve a disagreement peacefully.",answer:"Active listening, calm respectful language, taking turns, acknowledging feelings, fair compromise and seeking mediation."},
      {t:"Stewardship and care for creation",level:"Faith and environment",body:"Stewardship means caring responsibly for resources and the natural world. It can be expressed through avoiding waste, protecting living things, using water wisely and taking part in community conservation. Different faith traditions may explain stewardship in their own teachings.",steps:["Identify a shared resource that needs care.","Explain how careless use harms people or nature.","Choose a realistic conservation action.","Work with others and review the impact."],example:"A class can reduce waste by reusing suitable materials, sorting recyclables and keeping the school compound clean.",practice:"Suggest two ways learners can practise environmental stewardship.",answer:"Conserve water and electricity, plant and care for trees, avoid littering, reduce waste and protect habitats."},
      {t:"Integrity, peer pressure and responsible choices",level:"Life skills",body:"Integrity means acting honestly and consistently with sound values, even when no one is watching. Peer pressure can influence choices positively or negatively. Assertive communication helps a learner refuse unsafe or dishonest actions while maintaining respect.",steps:["Recognise the pressure or decision being presented.","Pause and consider possible consequences.","Compare the action with your values and responsibilities.","Say no clearly and respectfully when needed.","Seek help from a trusted adult if pressure or threats continue."],example:"A friend asks you to share answers during a test. You can say, 'I want us both to learn, so I will not help us cheat. Let's revise together afterwards.'",practice:"Write one respectful sentence a learner can use to refuse negative peer pressure.",answer:"For example: 'No, I am not comfortable doing that. Let's choose something safe and honest instead.'"}
    ],
    arts: [
      {t:"Music: rhythm, beat and simple notation",level:"Music",body:"Beat is the steady pulse in music. Rhythm is the pattern of long and short sounds and silences organised around the beat. Tempo describes speed, while dynamics describe loudness and softness. Symbols and simple notation help communicate musical ideas.",steps:["Listen and tap the steady beat.","Clap a rhythm pattern over the beat.","Identify repeated patterns and rests.","Use simple symbols or syllables to record a pattern.","Perform together while keeping a steady tempo."],example:"Clap four steady beats, then clap a pattern of two quick sounds followed by one longer sound and a rest.",practice:"Explain the difference between beat and rhythm.",answer:"Beat is the steady underlying pulse; rhythm is the pattern of sounds and silences arranged over that pulse."},
      {t:"Drama: role, movement and storytelling",level:"Performing arts",body:"Drama communicates ideas and experiences through role, action, voice, movement, space and audience interaction. A short scene needs a clear situation, characters, a problem and a resolution. Rehearse safely and respect every participant.",steps:["Choose a familiar theme or situation.","Agree on characters and a simple plot.","Plan dialogue, movement and use of space.","Rehearse voice projection and expression.","Perform and reflect respectfully on feedback."],example:"A short scene about water conservation can show a careless action, its effects and a community solution.",practice:"Name four elements that help communicate meaning in a drama performance.",answer:"Character, voice, movement, gesture, facial expression, space, plot and interaction with the audience."},
      {t:"Team games: tactics, fair play and inclusion",level:"Sports",body:"Team games require skills, communication, cooperation and respect for rules. Tactics are planned ways of achieving a goal. Inclusive participation adapts roles and activities so that learners with different abilities can contribute safely.",steps:["Understand the objective and rules of the game.","Practise basic movement and ball or object control skills.","Communicate and support teammates.","Use simple tactics such as creating space and passing.","Respect officials, opponents and safety instructions."],example:"In a passing game, teammates move into open space and communicate clearly so the player with the ball has safe passing options.",practice:"Give three examples of fair play during a team game.",answer:"Follow rules, respect officials, encourage teammates, avoid dangerous play, accept results and include all participants."}
    ]
  };
  lessons.forEach(subject => {
    const extras = additionalTopics[subject.id] || [];
    subject.topics.push(...extras);
  });

